import { useEffect, useState } from "react";
import axios from "axios";

export default function Perfil() {
  const [usuario, setUsuario] = useState(null);
  const [erro, setErro] = useState(null);
  const [carregando, setCarregando] = useState(true);

  useEffect(() => {
    axios.get("http://localhost:3001/usuarios") // 🔁 rota corrigida
      .then((res) => {
        if (Array.isArray(res.data) && res.data.length > 0) {
          setUsuario(res.data[0]); // pega o primeiro usuário, ajuste conforme sua lógica
        } else {
          setErro("Nenhum usuário encontrado.");
        }
      })
      .catch((err) => {
        console.error("Erro ao carregar perfil:", err);
        setErro("Erro ao carregar o perfil.");
      })
      .finally(() => setCarregando(false));
  }, []);

  if (carregando) return <p>🔄 Carregando perfil...</p>;
  if (erro) return <p>❌ {erro}</p>;

  return (
    <div>
      <h2>{usuario.nome}</h2>
      <p>Idade: {usuario.idade}</p>
      <p>Endereço: {usuario.rua}, {usuario.bairro}, {usuario.estado}</p>
      <p>Biografia: {usuario.biografia}</p>
      {usuario.imagem && (
        <img
          src={`http://localhost:3001${usuario.imagem}`}
          alt="Foto de perfil"
          width="200"
        />
      )}
    </div>
  );
}
